.box {
  position: static;   /* the initial value; writing it is only a reminder */
  top: 40px;          /* has no effect here */
  left: 40px;         /* has no effect here */
}

.card {
  position: relative;  /* the badge now measures against this box */
}

.card__tag {
  position: absolute;
  top: 8px;
  right: 8px;
}

.figure {
  position: relative;
}

.figure__cover {
  position: absolute;
  inset: 0;            /* top right bottom left all zero */
  background: rgb(12 18 28 / 45%);
}

.panel {
  position: absolute;
  inset: 0;
  margin: auto;        /* auto margins absorb the leftover space on both sides */
  width: 320px;
  height: 200px;
}

/* Shorter alternative: let the parent center the child. */
.backdrop {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
}

:root {
  --header-h: 64px;
}

.header {
  position: fixed;
  inset: 0 0 auto 0;   /* top 0, right 0, bottom auto, left 0 */
  height: var(--header-h);
  z-index: 10;
}

body {
  padding-top: var(--header-h);
}

html {
  /* Anchor links scroll 12px below the header instead of under it. */
  scroll-padding-top: calc(var(--header-h) + 12px);
}

.table-wrap {
  max-height: 360px;
  overflow: auto;      /* this element becomes the scrollport */
}

.table-wrap thead th {
  position: sticky;
  top: 0;
  background: #f4f7fb; /* must be opaque, or rows show through */
  border-bottom: 1px solid #d8dde6;
}

/* 1. The threshold is missing. */
.head { position: sticky; }               /* no top, no stickiness */

/* 2. An ancestor clips it. */
.wrapper { overflow: hidden; }            /* becomes the scrollport */

/* 3. No room to travel. */
.column { display: grid; }                /* stretch makes the child as tall as the parent */
.column > .head { position: sticky; top: 0; }
.column > .head { align-self: start; }    /* gives the element room to move */

.cover {
  position: absolute;
  inset: 0;               /* all four sides */
}

.gutter {
  position: absolute;
  inset: 12px 24px;       /* 12px top and bottom, 24px left and right */
}

.translated {
  position: absolute;
  inset-inline-start: 0;  /* left in English, right in Arabic or Hebrew */
}

/* Walk up from the absolute box and stop at the first match. */
.static-parent { position: static; }        /* skip */
.grid-parent { position: relative; }        /* stop here: its padding box wins */

.child {
  position: absolute;
  top: 0;             /* 0 from the padding edge of .grid-parent */
  left: 0;
}

/* Fixed boxes use the viewport unless an ancestor has transform,
   filter, perspective, contain: paint or content-visibility: auto. */

.widget {
  isolation: isolate;   /* like a z-index context, but no layer change */
  position: relative;
}

.widget__badge {
  position: absolute;
  z-index: 2;           /* cannot climb above the widget now */
}

:root {
  --z-base: 0;
  --z-header: 10;
  --z-dropdown: 20;
  --z-backdrop: 100;
  --z-modal: 110;
  --z-toast: 120;
}

.header { position: sticky; top: 0; z-index: var(--z-header); }
.backdrop { position: fixed; inset: 0; z-index: var(--z-backdrop); }
.modal { position: fixed; z-index: var(--z-modal); }

/* A child with z-index 9999 inside .header still loses to .backdrop,
   because the header's context caps it at 10. */

/* Phone layout first, no query needed. */
.grid {
  display: grid;
  gap: 16px;
  grid-template-columns: 1fr;
}

@media (min-width: 48em) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 64em) {
  .grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
  }
}

/* 48em is 768px at the default 16px root, and 960px at a 20px user setting. */
@media (min-width: 48em) {
  .layout {
    grid-template-columns: 220px 1fr;
  }
}

/* Pick the number where the content breaks, not the name of a device. */
@media (min-width: 60em) {
  .cards { grid-template-columns: repeat(3, 1fr); }
}

h1 {
  /* 28px minimum, 44px maximum, gentle growth between. */
  font-size: clamp(1.75rem, 1.25rem + 2.2vw, 2.75rem);
  line-height: 1.15;
}

.wrap {
  /* Cap the width and keep a gutter in one declaration. */
  width: min(1100px, 100% - 32px);
  margin-inline: auto;
}

.cards {
  display: grid;
  gap: 16px;
  /* min(100%, 240px) stops the track from overflowing a container
     narrower than 240px, which a bare 240px would do. */
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  padding: 0;
  margin: 0;
  list-style: none;
}

:root {
  --header-h: 56px;
}

html {
  scroll-padding-top: calc(var(--header-h) + 12px);
}

body {
  padding-top: var(--header-h);  /* reserve the header once */
}

@media (min-width: 40em) {
  :root { --header-h: 64px; }    /* padding and offset both follow */
}

/* Section by section alternative: */
#rooms, #rates { scroll-margin-top: calc(var(--header-h) + 12px); }

.panel {
  /* Shrinks and grows with the toolbar. */
  min-height: 100dvh;
}

.hero {
  /* The safe choice: never taller than the visible area. */
  min-height: 60svh;
}

/* Avoid 100vw for full width blocks: it includes the desktop scrollbar
   and can add a horizontal scrollbar. Use 100% instead. */
.full { width: 100%; }

.card-wrap {
  container-type: inline-size;  /* makes this box a query container */
  container-name: card;
}

.card {
  display: grid;
  gap: 8px;
}

@container card (min-width: 400px) {
  .card {
    /* Side by side only when the card itself is wide enough. */
    grid-template-columns: 120px 1fr;
    align-items: center;
  }
}

/* Media cannot overflow its container. */
img,
video,
iframe,
svg {
  max-width: 100%;
  height: auto;
}

/* Long words and URLs wrap instead of pushing the line wide. */
p, li {
  overflow-wrap: anywhere;
}

